'use strict';
const $=id=>document.getElementById(id),fmt=n=>Math.round(n).toLocaleString('en-US');let current,pending=null;
function el(tag,text,cls){const e=document.createElement(tag);if(text!==undefined)e.textContent=text;if(cls)e.className=cls;return e;}
function render(){const d=current=DemoEngine.aggregate($('team').value,$('period').value);$('metrics').replaceChildren(...[['Requests opened',fmt(d.opened),`${d.change.toFixed(1)}% vs prior period`],['Resolution rate',d.rate.toFixed(1)+'%','Resolved ÷ opened'],['SLA attainment',d.sla.toFixed(1)+'%','Target ≥ 90% · weighted by resolved'],['Net backlog change',(d.backlog>0?'+':'')+fmt(d.backlog),'Opened minus resolved · not total backlog']].map(([t,v,n])=>{const e=el('div',undefined,'metric');e.append(el('small',t),el('strong',v),el('small',n));return e;}));
const max=Math.max(...d.weeks.flatMap(w=>[w.opened,w.resolved]))*1.2,ns='http://www.w3.org/2000/svg';const svg=document.createElementNS(ns,'svg');svg.setAttribute('viewBox','0 0 520 190');svg.setAttribute('role','img');svg.setAttribute('aria-label','Opened versus resolved requests. Exact values below in the data table.');function shape(tag,attrs){const e=document.createElementNS(ns,tag);for(const [k,v]of Object.entries(attrs))e.setAttribute(k,v);svg.append(e);return e;}for(let i=0;i<4;i++)shape('line',{x1:30,x2:515,y1:15+i*45,y2:15+i*45,stroke:'#25303c'});d.weeks.forEach((w,i)=>{const x=50+i*450/d.weeks.length;for(const [key,offset,color]of [['opened',0,'#7af5d2'],['resolved',25,'#ae9cff']]){const h=w[key]/max*145,r=shape('rect',{x:x+offset,y:160-h,width:20,height:h,fill:color,rx:3});const title=document.createElementNS(ns,'title');title.textContent=`Week ${w.week}: ${w[key]} ${key}`;r.append(title);}shape('text',{x,y:183,fill:'#98a8b9','font-size':11}).textContent='Week '+w.week;});$('chart').replaceChildren(svg);
$('risks').replaceChildren();for(const [warn,title,body]of [[d.backlog>0,'Backlog pressure',`${fmt(d.backlog)} net requests ${d.backlog>0?'added. Review capacity and aging requests.':'cleared. Maintain capacity and monitor demand.'}`],[d.sla<90,'Service target',`${d.sla.toFixed(1)}% SLA vs 90% target. ${d.sla<90?'Assign owners to overdue work.':'Continue weekly monitoring.'}`]]){const e=el('div',undefined,'risk');e.append(el('strong',(warn?'△ ':'✓ ')+title,warn?'warn':'good'),el('p',body));$('risks').append(e);}const table=el('table'),head=table.createTHead().insertRow();['Team','Week','Opened','Resolved','SLA %'].forEach(v=>{const th=el('th',v);th.scope='col';head.append(th);});const body=table.createTBody();d.selected.forEach(r=>{const tr=body.insertRow();[r.team,r.week,r.opened,r.resolved,r.sla].forEach(v=>tr.insertCell().textContent=v);});$('dataTable').replaceChildren(table);$('brief').textContent='Generate a briefing for the current selection.';}
$('team').onchange=render;$('period').onchange=render;$('summary').onclick=()=>{const d=current;$('brief').textContent=`EXECUTIVE BRIEF · ${$('team').value} · Last ${$('period').value} weeks\n\n${fmt(d.opened)} requests opened and ${fmt(d.resolved)} resolved (${d.rate.toFixed(1)}% resolution rate). Demand changed ${d.change.toFixed(1)}% from the preceding window. Net backlog changed by ${d.backlog>0?'+':''}${fmt(d.backlog)} requests. SLA attainment: ${d.sla.toFixed(1)}%, target: 90%.\n\nRecommended actions: ${d.backlog>0?'Review capacity and prioritize aging requests.':'Maintain capacity and monitor demand.'} ${d.sla<90?'Assign owners to overdue cases and review SLA exceptions.':'Continue weekly SLA monitoring.'}\n\nGenerated locally using explicit rules and fictional data. No language model used.`;};
$('download').onclick=()=>{const csv=['team,week,opened,resolved,sla',...current.selected.map(r=>[r.team,r.week,r.opened,r.resolved,r.sla].join(','))].join('\n'),url=URL.createObjectURL(new Blob([csv],{type:'text/csv'})),a=el('a');a.href=url;a.download='fictional-operations.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
const samples={outage:'Our fictional customer portal is offline. Multiple teams cannot submit requests. Please investigate this critical outage.',access:'Please review an access request for a fictional employee joining the reporting team. The system owner needs to approve read-only permissions.',invoice:'Please review invoice DEMO-1042 for fictional company Northstar. We need clarification about the billing period before payment.'};
function mark(index){document.querySelectorAll('#flow span').forEach((s,i)=>s.classList.toggle('active',i<=index));}function invalidate(){pending=null;$('approve').disabled=true;$('reject').disabled=true;$('result').textContent='Analyze the current request before approving.';mark(-1);}let started=false;function log(s){if(!started){$('log').replaceChildren();started=true;}$('log').prepend(el('li',new Date().toLocaleTimeString()+' · '+s));}
$('sample').onchange=()=>{if(samples[$('sample').value]){$('request').value=samples[$('sample').value];invalidate();}};$('request').oninput=invalidate;
$('analyze').onclick=()=>{invalidate();try{const input=$('request').value,r=DemoEngine.classify(input);pending={input,result:r};$('validation').textContent='Analysis complete. Review the draft before approving.';$('result').replaceChildren();for(const [name,value]of [['Category',r.category],['Priority',r.priority],['Route',r.route],['Reason',r.reason],['Next step',r.next]]){const p=el('p');p.append(el('strong',name+': '),document.createTextNode(value));$('result').append(p);}$('result').append(el('blockquote',r.draft));$('approve').disabled=false;$('reject').disabled=false;mark(3);log(`Classified ${r.category}, ${r.priority} priority. Awaiting human approval.`);}catch(e){$('validation').textContent=e.message;log('Validation failed. No draft created.');}};
$('approve').onclick=()=>{if(!pending||pending.input!==$('request').value){invalidate();return;}log(`Human approved. SIMULATED routing to ${pending.result.route}. Nothing sent.`);$('validation').textContent='Approved simulation complete. No external action occurred.';pending=null;$('approve').disabled=true;$('reject').disabled=true;mark(4);};$('reject').onclick=()=>{if(!pending)return;log('Human rejected draft. No action executed.');invalidate();$('validation').textContent='Draft rejected. Edit or analyze again.';};render();
